#include <iostream>
using namespace std;

#define VERSION {v}
#define CATS {c}

int main() {
    int per = 0;
#if defined(VERSION) && VERSION >= 2
    per = 3;
#else
    per = 1;
#endif
    cout << CATS << " 只猫，一共要 " << CATS * per << " 条小鱼干" << endl;
    return 0;
}
